  const exportSettingsHistory = () => { const markdown = filteredSettingsHistory.map((record) => `## ${record.label}\n\n- Action: ${record.action}\n- Time: ${record.timestamp}\n- Language: ${record.effective.language}\n- Theme: ${record.effective.theme}\n- Dock: ${record.effective.dock}\n- Density: ${record.effective.density}\n- Accent: ${record.effective.accent}\n- English tone: ${record.effective.funnyEnglish}\n- Cantonese tone: ${record.effective.funnyCantonese}\n- Message emoji: ${record.effective.showEmojis ? "on" : "off"}`).join("\n\n"); const url = URL.createObjectURL(new Blob([`${markdown}\n`], { type: "text/markdown;charset=utf-8" })); const anchor = document.createElement("a"); anchor.href = url; anchor.download = "winforge-settings-history.md"; anchor.click(); setTimeout(() => URL.revokeObjectURL(url), 0); setToast("Filtered settings history exported locally."); };
  const restoreSettingsRecord = () => { const record = settingsHistory.records.find((item) => item.id === settingsRestoreId); if (!record) { setSettingsRestoreId(null); return; } const next = { ...prefs, ...record.effective, settingsOwnership: record.ownership }; setPrefs(next); appendSettingsHistory("restored", `Restored ${record.label}`, next); setSettingsRestoreId(null); setToast("Settings history record restored."); };
  const commands = [...TABS.map((tab) => ({ id: tab.id, label: dual(tab.en, tab.yue, language), detail: dual("Open site destination", "開啟網站目的地", language), action: () => selectTab(tab.id, `panel-${tab.id}`) })), { id: "search", label: dual("Focus site search", "跳去網站搜尋", language), detail: dual("Search features and articles", "搜尋功能同文章", language), action: () => selectTab("features", "site-search") }, { id: "emoji-preference", label: dual("Show emojis in dialogs and message boxes", "喺對話框同訊息框顯示 emoji", language), detail: dual("Open the persisted decoration preference", "開啟已保存嘅裝飾偏好", language), action: () => { setSettingsQuery(""); selectTab("settings", "emoji-preference"); } }, { id: "vocabulary-upload", label: dual("Upload personal vocabulary", "上載個人詞彙", language), detail: dual("Choose or replace the local JSON file", "揀選或取代本機 JSON 檔案", language), action: () => { setSettingsQuery(""); selectTab("settings", "site-vocabulary-file"); setTimeout(() => document.getElementById("site-vocabulary-file")?.click(), 60); } }, { id: "vocabulary-status", label: dual("Personal vocabulary status", "個人詞彙狀態", language), detail: dual("Open the loaded, invalid, or no-file state", "開啟已載入、無效或未有檔案狀態", language), action: () => { setSettingsQuery(""); selectTab("settings", "site-vocabulary-status"); } }, { id: "vocabulary-clear", label: dual("Clear personal vocabulary", "清除個人詞彙", language), detail: dual("Purge the local cache and restore shipped wording", "清除本機快取並回復原裝文字", language), action: () => { setSettingsQuery(""); selectTab("settings", "site-vocabulary-status"); clearVocabulary(); } }, { id: "reset", label: dual("Reset site preferences", "重設網站偏好", language), detail: dual("Review and confirm restoring documented defaults", "檢視並確認回復文件列明嘅預設值", language), action: openResetConfirmation }];
  commands.push({ id: "notifications", label: dual("Notification center", "通知中心", language), detail: dual("Open persistent local notification history", "開啟持久本機通知記錄", language), action: openNotifications });
  commands.push({ id: "settings-history", label: dual("Settings history", "設定記錄", language), detail: dual("Browse and restore local settings revisions", "瀏覽同還原本機設定版本", language), action: () => setSettingsHistoryOpen(true) });
  commands.push({ id: "app-logo", label: dual("App logo customization", "應用程式標誌自訂", language), detail: dual("Open shipped presets and local custom image controls", "開啟內置預設同本機自訂圖片控制", language), action: () => { setSettingsQuery(""); selectTab("settings", "site-logo-settings"); } });
  commands.push({ id: "app-logo-upload", label: dual("Upload custom app logo", "上載自訂應用程式標誌", language), detail: dual("Choose or replace a bounded local PNG or JPEG", "揀選或取代有限度本機 PNG 或 JPEG", language), action: () => { setSettingsQuery(""); selectTab("settings", "site-logo-file"); setTimeout(() => document.getElementById("site-logo-file")?.click(), 60); } });
  commands.push({ id: "app-logo-reset", label: dual("Reset app logo", "重設應用程式標誌", language), detail: dual("Restore the shipped Forge mark", "回復原裝 Forge 標誌", language), action: clearCustomLogo });
  commands.push({ id: "tab-docking", label: dual("Tab position", "分頁位置", language), detail: dual("Choose left, right, top, or bottom docking", "揀左、右、頂或者底部停靠", language), action: () => { setSettingsQuery(""); selectTab("settings", "tab-docking-setting"); } });
  commands.push({ id: "settings-search", label: dual("Search site settings", "搜尋網站設定", language), detail: dual("Focus the top-level Settings search and regex builder", "聚焦頂層設定搜尋同正規表示式工具", language), action: () => selectTab("settings", "settings-search") });
  let palettePattern: RegExp | null = null; let palettePatternError = "";
  if (paletteRegex && paletteQuery) try { palettePattern = new RegExp(paletteQuery, `${paletteFlags.i ? "i" : ""}${paletteFlags.m ? "m" : ""}`); } catch (error) { palettePatternError = error instanceof Error ? error.message : "Invalid regular expression"; }
  let paletteMatches: RegExpMatchArray[] = [];
