  const filteredCommands = commands.filter((command) => { const text = `${command.label} ${command.detail}`; return !paletteQuery || (paletteRegex ? !!palettePattern?.test(text) : text.toLocaleLowerCase().includes(paletteQuery.toLocaleLowerCase())); });
  let changelogPattern: RegExp | null = null;
